  if(!$this->ok($o)||'PROFILE_EXAMINATION_DELIBERATION_OPENED_PENDING_RECONCILIATION'!==($o['status']??null)||true!==($o['deliberation_open']??null)||true!==($o['reconciliation_authority_exercisable']??null)||$authorityId!==($a['authority_id']??null)||true!==($a['authority_single_use']??null)||false!==($o['vote_authority']??null)||false!==($o['aggregation_authority']??null)||false!==($o['senate_disposition_authority']??null))throw new \RuntimeException('S291_MODEL_BOUND_RECONCILIATION_CHAIN_INVALID');
